const STY = (bg, l, t, w, h) => `position:absolute;left:${l}px;top:${t}px;width:${w}px;height:${h}px;display:flex;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#0b1020;font-family:inherit;font-weight:800;font-size:48px;line-height:1.1;opacity:0;`;
const G1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const G2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <svg style="position:absolute;top:0;left:0;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.3">
    <path id="l1" d="M470 440 L470 300" />
    <path id="l2" d="M470 620 L470 760" />
  </svg>
  <div id="c0" style="${STY(G1, 120, 440, 700, 180)}">ROGUE AGENT<br>INCIDENTS</div>
  <div id="c1" style="${STY(G2, 120, 120, 700, 180)}">OPENAI:<br>RARE OUTLIER</div>
  <div id="c2" style="${STY(G2, 120, 760, 700, 180)}">CALIFORNIA:<br>PUBLIC NUISANCE</div>
`;

const cs = [0, 1, 2].map(i => root.querySelector('#c' + i));
const ls = [1, 2].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const limit = d * 0.55;
  const curT = Math.min(t, limit);

  // Hub: Rogue Agent Incident
  const s0 = spr(curT, 0.2, 0.85, 10);
  cs[0].style.opacity = clamp((curT - 0.1) * 4);
  cs[0].style.transform = `scale(${s0})`;

  // Connection 1 and OpenAI Claim
  const d1 = clamp((curT - 0.7) * 3);
  ls[0].el.style.strokeDashoffset = ls[0].len * (1 - d1);

  const s1 = spr(curT, 1.0, 0.85, 10);
  cs[1].style.opacity = clamp((curT - 0.9) * 4);
  cs[1].style.transform = `translateY(${lerp(30, 0, E_OUT(clamp((curT - 0.9) * 2)))}px) scale(${s1})`;

  // Connection 2 and California Claim
  const d2 = clamp((curT - 1.6) * 3);
  ls[1].el.style.strokeDashoffset = ls[1].len * (1 - d2);

  const s2 = spr(curT, 1.9, 0.85, 10);
  cs[2].style.opacity = clamp((curT - 1.8) * 4);
  cs[2].style.transform = `translateY(${lerp(-30, 0, E_OUT(clamp((curT - 1.8) * 2)))}px) scale(${s2})`;

  // Stabilization at limit
  if (t >= limit) {
    cs.forEach(c => { c.style.opacity = 1; });
    ls.forEach(l => { l.el.style.strokeDashoffset = 0; });
    cs[0].style.transform = 'scale(1)';
    cs[1].style.transform = 'translateY(0px) scale(1)';
    cs[2].style.transform = 'translateY(0px) scale(1)';
  }
}
